import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Pluggable Module Composition","description":"","frontmatter":{"title":"Pluggable Module Composition","type":"adr","date":"2026-08-24T00:00:00.000Z","status":"proposed","status_note":"Accepted — composition is per module; plugins declare their passes."},"headers":[],"relativePath":"handl/project/adrs/0028-pluggable-module-composition.md","filePath":"vendored/handl/project/adrs/0028-pluggable-module-composition.md"}`),a={name:`handl/project/adrs/0028-pluggable-module-composition.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0028-pluggable-module-composition" tabindex="-1">ADR-0028: Pluggable Module Composition <a class="header-anchor" href="#adr-0028-pluggable-module-composition" aria-label="Permalink to “ADR-0028: Pluggable Module Composition”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Replace the static <code>frontend_for(format)</code> and monolithic <code>Dialect</code></strong> with per-module composition driven by a <code>module.toml</code> manifest.</li><li><strong>Every module folder may carry <code>module.toml</code></strong> (language kit + per-stage plugins); nested modules may carry their own, so a project can mix syntaxes and toolchains.</li><li><strong>Naming is <code>handl-*</code></strong> for kits, lexers, parsers, typecheckers, formatters, passes and multi-pass plugins — deterministic discovery, no collisions.</li><li><strong>A <code>Composer</code> assembles the pipeline</strong> from the manifest plus each plugin&#39;s pass declarations, and validates coverage and conflicts before running. Stages invoke the <code>Composer</code>, not <code>frontend_for</code>.</li><li><strong>All passes are pluggable</strong> — lexer, parser, resolve, typecheck, format, generate — each plugin declares the passes it implements; orchestrators run the configured plugins in order.</li><li><strong>AST strategy</strong>: plugins may produce different ASTs; a <code>lower</code>/canonicalize pass to a shared IR is the recommended default, and opting out requires a complete AST-specific chain.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p><code>frontend_for(format)</code> was a static map and <code>Dialect</code> was monolithic, so a new syntax or a per-module toolchain meant editing the compiler. A manifest plus pass declarations makes composition data and lets nested modules differ.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>One global frontend</strong> — modules may mix syntaxes.</li><li><strong>A monolithic <code>Dialect</code> trait</strong> — passes are plugins.</li><li><strong>Free-form plugin names</strong> — the <code>handl-*</code> scheme keeps discovery deterministic.</li><li><strong>Heterogeneous ASTs downstream</strong> — lower to a canonical IR or supply a full chain.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Composition is data; the <code>Composer</code> validates before execution.</li><li>Plugins declare passes once; manifests only override/extend.</li><li>Lowering becomes the seam between plugin-specific and shared ASTs.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>crates/handl-frontend/</code> — the <code>Composer</code>.</li><li><code>handl-packages/*/module.toml</code> — per-module manifests.</li><li>Plugin metadata (<code>passes = [...]</code>) and composer tests.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Manifest format, naming, composer behavior, pass declarations and AST strategy: +<a href="./../design/0028-pluggable-module-composition.html"><code>design/0028-pluggable-module-composition.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};